-- Identity & access: users, roles, refresh-token sessions and the security audit trail.
-- Primary keys are UUIDv7 generated by the application (time-ordered, index-friendly).

create table users
(
    id                    uuid primary key,
    email                 varchar(320) not null,
    password_hash         varchar(255) not null,
    full_name             varchar(200) not null,
    enabled               boolean      not null default true,
    failed_login_attempts integer      not null default 0,
    locked_until          timestamptz,
    last_login_at         timestamptz,
    password_changed_at   timestamptz  not null,
    created_at            timestamptz  not null,
    updated_at            timestamptz  not null,
    version               bigint       not null default 0,
    constraint uq_users_email unique (email),
    -- Emails are normalised by the application; the database refuses anything that slipped through.
    constraint ck_users_email_normalised check (email = lower(btrim(email)))
);

create table user_roles
(
    user_id uuid        not null references users (id) on delete cascade,
    role    varchar(32) not null,
    primary key (user_id, role)
);

create index ix_user_roles_role on user_roles (role);

-- One row per issued refresh token. Tokens sharing a session_id form a rotation family:
-- presenting an already-rotated token revokes the whole session (token-theft detection).
create table refresh_tokens
(
    id                 uuid primary key,
    user_id            uuid         not null references users (id) on delete cascade,
    session_id         uuid         not null,
    token_hash         varchar(64)  not null, -- SHA-256 (hex) of the opaque token; the raw value is never stored
    client_type        varchar(16)  not null,
    session_started_at timestamptz  not null,
    expires_at         timestamptz  not null,
    last_used_at       timestamptz,
    revoked_at         timestamptz,
    revoked_reason     varchar(32),
    replaced_by_id     uuid,
    user_agent         varchar(512),
    ip_address         varchar(64),
    created_at         timestamptz  not null,
    updated_at         timestamptz  not null,
    version            bigint       not null default 0,
    constraint uq_refresh_tokens_token_hash unique (token_hash)
);

create index ix_refresh_tokens_user_active on refresh_tokens (user_id) where revoked_at is null;
create index ix_refresh_tokens_session on refresh_tokens (session_id);
create index ix_refresh_tokens_expires_at on refresh_tokens (expires_at);

-- Append-only security/audit log. No FK to users: the trail must outlive the accounts it describes.
create table audit_events
(
    id            uuid primary key,
    occurred_at   timestamptz  not null,
    action        varchar(64)  not null,
    outcome       varchar(16)  not null,
    actor_user_id uuid,
    actor_email   varchar(320),
    target_type   varchar(64),
    target_id     varchar(64),
    ip_address    varchar(64),
    user_agent    varchar(512),
    request_id    varchar(64),
    details       jsonb
);

create index ix_audit_events_occurred_at on audit_events (occurred_at desc);
create index ix_audit_events_actor on audit_events (actor_user_id, occurred_at desc);
create index ix_audit_events_action on audit_events (action, occurred_at desc);
